-- Inject after the candidate migration body inside an outer transaction; caller must ROLLBACK.
DO $test$
DECLARE
  m uuid; n constant uuid:='d1000000-0000-4000-8000-000000000001'; r jsonb; rejected boolean;
BEGIN
  SELECT user_id INTO STRICT m FROM public.dg_user_profiles WHERE active AND is_manager ORDER BY user_id LIMIT 1;
  IF EXISTS(SELECT 1 FROM public.dg_native_jobs WHERE visible_identifier IN('DG-999901','DG-999902','DG-999903','DG-999904','DG-999905','JOB-999991')) OR EXISTS(SELECT 1 FROM public.dg_production_bookings WHERE booking_id LIKE 'NONPROD-DELETE-%') THEN RAISE EXCEPTION 'fixture.identifier_collision'; END IF;
  UPDATE public.dg_native_jobs SET archived_at=clock_timestamp(),archived_by_user_id=m,archive_reason='NONPROD TEST' WHERE internal_job_id='a1000000-0000-4000-8000-000000000003';

  rejected:=false;BEGIN DELETE FROM public.dg_production_booking_moves WHERE booking_id='NONPROD-DELETE-TARGET-BOOKING';EXCEPTION WHEN OTHERS THEN rejected:=true;END;IF NOT rejected THEN RAISE EXCEPTION 'direct_move_delete_not_rejected';END IF;
  rejected:=false;BEGIN UPDATE public.dg_production_booking_moves SET actor_user_id=null,reason='NONPROD FORBIDDEN MUTATION' WHERE booking_id='NONPROD-DELETE-TARGET-BOOKING';EXCEPTION WHEN OTHERS THEN rejected:=true;END;IF NOT rejected THEN RAISE EXCEPTION 'extended_move_mutation_not_rejected';END IF;
  rejected:=false;BEGIN DELETE FROM public.dg_production_booking_completion_events WHERE booking_id='NONPROD-DELETE-TARGET-BOOKING';EXCEPTION WHEN OTHERS THEN rejected:=true;END;IF NOT rejected THEN RAISE EXCEPTION 'direct_completion_delete_not_rejected';END IF;
  rejected:=false;BEGIN DELETE FROM public.dg_production_status_events WHERE booking_id='NONPROD-DELETE-TARGET-BOOKING';EXCEPTION WHEN OTHERS THEN rejected:=true;END;IF NOT rejected THEN RAISE EXCEPTION 'direct_status_delete_not_rejected';END IF;
  PERFORM set_config('request.jwt.claim.sub',n::text,true);rejected:=false;BEGIN PERFORM public.dg_delete_native_job('a1000000-0000-4000-8000-000000000003',2);EXCEPTION WHEN OTHERS THEN IF SQLERRM='native_job.manager_required' THEN rejected:=true;ELSE RAISE;END IF;END;IF NOT rejected OR NOT EXISTS(SELECT 1 FROM public.dg_native_jobs WHERE internal_job_id='a1000000-0000-4000-8000-000000000003') THEN RAISE EXCEPTION 'nonmanager_contract_failed';END IF;
  PERFORM set_config('request.jwt.claim.sub',m::text,true);rejected:=false;BEGIN PERFORM public.dg_delete_native_job('a1000000-0000-4000-8000-000000000004',3);EXCEPTION WHEN OTHERS THEN IF SQLERRM='native_job.stale_revision' THEN rejected:=true;ELSE RAISE;END IF;END;IF NOT rejected OR NOT EXISTS(SELECT 1 FROM public.dg_native_jobs WHERE internal_job_id='a1000000-0000-4000-8000-000000000004') THEN RAISE EXCEPTION 'stale_contract_failed';END IF;
  CREATE TABLE public.nonprod_delete_late_dependency(job_id uuid REFERENCES public.dg_native_jobs(internal_job_id) ON DELETE RESTRICT);INSERT INTO public.nonprod_delete_late_dependency VALUES('a1000000-0000-4000-8000-000000000005');rejected:=false;BEGIN PERFORM public.dg_delete_native_job('a1000000-0000-4000-8000-000000000005',5);EXCEPTION WHEN foreign_key_violation THEN rejected:=true;END;IF NOT rejected OR NOT EXISTS(SELECT 1 FROM public.dg_native_job_lines WHERE internal_job_id='a1000000-0000-4000-8000-000000000005') THEN RAISE EXCEPTION 'atomicity_contract_failed';END IF;
  r:=public.dg_delete_native_job('a1000000-0000-4000-8000-000000000001',3);IF r<>jsonb_build_object('internal_job_id','a1000000-0000-4000-8000-000000000001'::uuid,'visible_identifier','DG-999901','deleted_production_bookings',1)THEN RAISE EXCEPTION 'structured_result_failed: %',r;END IF;
  IF EXISTS(SELECT 1 FROM public.dg_native_jobs WHERE internal_job_id='a1000000-0000-4000-8000-000000000001')OR EXISTS(SELECT 1 FROM public.dg_native_job_lines WHERE internal_job_id='a1000000-0000-4000-8000-000000000001')OR EXISTS(SELECT 1 FROM public.dg_native_job_create_commands WHERE internal_job_id='a1000000-0000-4000-8000-000000000001')OR EXISTS(SELECT 1 FROM public.dg_production_bookings WHERE booking_id='NONPROD-DELETE-TARGET-BOOKING')OR EXISTS(SELECT 1 FROM public.dg_calendar_links WHERE link_id='NONPROD-DELETE-TARGET-LINK')OR EXISTS(SELECT 1 FROM public.dg_production_booking_moves WHERE booking_id='NONPROD-DELETE-TARGET-BOOKING')OR EXISTS(SELECT 1 FROM public.dg_production_booking_completion_events WHERE booking_id='NONPROD-DELETE-TARGET-BOOKING')OR EXISTS(SELECT 1 FROM public.dg_production_status_events WHERE booking_id='NONPROD-DELETE-TARGET-BOOKING')THEN RAISE EXCEPTION 'manager_cleanup_failed';END IF;
  IF NOT EXISTS(SELECT 1 FROM public.dg_native_jobs WHERE internal_job_id='a1000000-0000-4000-8000-000000000002')OR NOT EXISTS(SELECT 1 FROM public.dg_production_bookings WHERE booking_id='NONPROD-DELETE-UNRELATED-BOOKING')OR NOT EXISTS(SELECT 1 FROM public.dg_calendar_links WHERE link_id='NONPROD-DELETE-UNRELATED-LINK')OR NOT EXISTS(SELECT 1 FROM public.dg_production_booking_moves WHERE booking_id='NONPROD-DELETE-UNRELATED-BOOKING')OR NOT EXISTS(SELECT 1 FROM public.dg_production_booking_completion_events WHERE booking_id='NONPROD-DELETE-UNRELATED-BOOKING')OR NOT EXISTS(SELECT 1 FROM public.dg_production_status_events WHERE booking_id='NONPROD-DELETE-UNRELATED-BOOKING')THEN RAISE EXCEPTION 'unrelated_preservation_failed';END IF;
  PERFORM public.dg_delete_native_job('a1000000-0000-4000-8000-000000000003',2);PERFORM public.dg_delete_native_job('a1000000-0000-4000-8000-000000000006',1);IF NOT EXISTS(SELECT 1 FROM public.dg_jobs WHERE job_id='JOB-999991')OR NOT EXISTS(SELECT 1 FROM public.dg_job_lines WHERE job_id='JOB-999991')THEN RAISE EXCEPTION 'legacy_source_deleted';END IF;
END;
$test$;
